(50819, 'Psalms 122:4', 'Psalms', 122, 4, 'دا هغه ځای دی چې راځي ورته قبیلې قبیلې د څښتن چې اسراییلو ته د هغه د اوامرو مطابق د هغه د نوم صفت وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms122_verse_4.mp3', '', 1761754199, 1761754199),
(50820, 'Psalms 122:5', 'Psalms', 122, 5, 'ځکه تخت د عدالت دی ټینګ په هغه ځای کې یعنې د داود د خاندان تخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms122_verse_5.mp3', '', 1761754199, 1761754199),
(50821, 'Psalms 122:6', 'Psalms', 122, 6, 'وکړئ دعا د سلامتۍ د اورشلیم دپاره چې ورته ګران یې هغه خلک دې نېکمرغه اوسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms122_verse_6.mp3', '', 1761754199, 1761754199),
