(50873, 'Numbers 23:19', 'Numbers', 23, 19, 'خدای د خلکو په شان نه دی چې دروغ ووایي انسان نه دی چې بدله اراده کړي رسوي سرته چې کړي کومې وعدې څه چې وایي هغه کاندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers23_verse_19.mp3', '', 1761754199, 1761754199),
(50874, 'Numbers 23:20', 'Numbers', 23, 20, 'ماته شوې لارښوونه چې زه ورکړم برکت خدای چې کوم وخت کې ورکوي برکت هغه زه بېرته ګرځولی نه شم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers23_verse_20.mp3', '', 1761754199, 1761754199),
