(50879, 'Numbers 23:25', 'Numbers', 23, 25, 'نو بالاق بلعام ته وویل: «که چېرې ته نه غواړې چې هغوی ته لعنت ووایې، نو برکت هم مه ورکوه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers23_verse_25.mp3', '', 1761754199, 1761754199),
(50880, 'Numbers 23:26', 'Numbers', 23, 26, 'بلعام په ځواب کې وویل: «ما مخکې تاته وویل چې زه به هرڅه د څښتن د وینا سره سم کوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers23_verse_26.mp3', '', 1761754199, 1761754199),
(50881, 'Numbers 23:27', 'Numbers', 23, 27, 'بالاق بلعام ته وویل: «ما سره راشه چې یو بل ځای ته دې بوځم. کېدای شي چې خدای تا پرېږدي چې زما دپاره د هغه ځای نه په اسراییلیانو باندې لعنت ووایې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers23_verse_27.mp3', '', 1761754199, 1761754199),
