(50886, 'Leviticus 17:2', 'Leviticus', 17, 2, 'چې هارون او د هغه زامنو او د اسراییلو ټول قوم ته لاندېني حکمونه ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_2.mp3', '', 1761754199, 1761754199),
(50887, 'Leviticus 17:5', 'Leviticus', 17, 5, 'د دې حکم معنی دا ده چې د اسراییلو خلک به له همدې وخت څخه څښتن ته هغه حیوانات راوړي چې په صحرا کې یې حلالول. هغوی باید هغه کاهن ته د سپېڅلې خېمې د دروازې خولې ته راولي او د سلامتۍ د نذرانو په توګه دې قرباني کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_5.mp3', '', 1761754199, 1761754199),
(50888, 'Leviticus 17:6', 'Leviticus', 17, 6, 'کاهن دې د سپېڅلې خېمې د دروازې په خوله کې هغه وینه د څښتن د قربانۍ په ځای باندې وشیندي او وازګه دې وسوځوي چې بوی یې په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_6.mp3', '', 1761754199, 1761754199),
(50889, 'Leviticus 17:7', 'Leviticus', 17, 7, 'د اسراییلو قوم باید نور په صحرا کې د هغو پېریانو دپاره قرباني ونه کړي چې د سېرلیو په شان ښکاري او په دې کار سره دې د څښتن سره بې وفایي نه کوي. د اسراییلو قوم باید تل ترتله په دې حکم باندې عمل وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_7.mp3', '', 1761754199, 1761754199),
(50890, 'Leviticus 17:8', 'Leviticus', 17, 8, 'که چېرې کوم اسراییلی یا پردی کس چې د دوی په منځ کې اوسیږي، سوځېدونکې نذرانه یا کومه بله قرباني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_8.mp3', '', 1761754199, 1761754199),
(50891, 'Leviticus 17:9', 'Leviticus', 17, 9, 'څښتن ته د نذرانې په توګه د سپېڅلې خېمې د دروازې د خولې څخه پرته په بل هرځای کې وړاندې کړي، د خدای د قوم څخه به وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_9.mp3', '', 1761754199, 1761754199),
(50892, 'Leviticus 17:10', 'Leviticus', 17, 10, 'که چېرې کوم اسراییلی یا هغه پردی کس چې د دوی په منځ کې اوسیږي کومه وینه وخوري، څښتن وایي چې د هغه په خلاف به شي او د خپل قوم څخه به یې وشړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_10.mp3', '', 1761754199, 1761754199),
(50893, 'Leviticus 17:11', 'Leviticus', 17, 11, 'د هر ژوندي شي ژوند په وینه کې دی او څښتن هغه د اسراییلو قوم ته ورکړې ده، د دې په خاطر چې د قربانۍ په ځای باندې د ځان دپاره کفاره ادا کړي. همدا وینه ده چې د یو چا د ژوند دپاره کفاره ادا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_11.mp3', '', 1761754199, 1761754199),
(50894, 'Leviticus 17:12', 'Leviticus', 17, 12, 'په دې خاطر څښتن د اسراییلو قوم ته ویلي دي چې نه به دوی او نه به هغه پردی کس چې د دوی په منځ کې اوسیږي، وینه وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_12.mp3', '', 1761754199, 1761754199),
(50895, 'Leviticus 17:13', 'Leviticus', 17, 13, 'که چېرې کوم اسراییلی یا پردی کس چې د دوی په منځ کې اوسیږي، یو داسې حیوان یا مرغۍ ښکار کړي چې هغه حلال وي، باید د هغه وینه په ځمکه باندې تویه کړي او په خاورو باندې دې پټه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_13.mp3', '', 1761754199, 1761754199),
(50896, 'Leviticus 17:14', 'Leviticus', 17, 14, 'د هر ژوندي شي ژوند په وینه کې دی، نو په دې خاطر څښتن د اسراییلو قوم ته ویلي دي چې باید د هېڅ یو ژوندي شي وینه ونه خوري. هرڅوک چې هغه وخوري، باید د خدای د قوم څخه وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_14.mp3', '', 1761754199, 1761754199),
(50897, 'Leviticus 17:15', 'Leviticus', 17, 15, 'هرڅوک، که هغه اسراییلی یا پردی وي د یو داسې حیوان غوښه وخوري چې په خپل مرګ باندې مړ شوی وي یا د وحشي حیواناتو له خوا وژل شوی وي، باید خپل کالي ووینځي او غسل دې وکړي. هغه به تر ماښامه پورې ناپاک وي، بیا به پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_15.mp3', '', 1761754199, 1761754199),
(50898, 'Leviticus 17:16', 'Leviticus', 17, 16, 'خو که چېرې هغه خپل کالي ونه وینځي او غسل ونه کړي، نو د خپلو بدو سزا به وویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus17_verse_16.mp3', '', 1761754199, 1761754199),
(50899, 'Hosea 7:1', 'Hosea', 7, 1, 'څښتن وایي:«کله چې زه وغواړم خپلو خلکو اسراییلو ته روغتیا ورکړم او هغوی یوځل بیا نېکمرغه کړم، نو د اسراییلو د خلکو بدکاري به ښکاره شي او د سامریې د خلکو بد عملونه به څرګند شي. هغوی یو د بله سره ټګي کوي. د خلکو په کورونو باندې وراوړي او غلاګانې کوي او په کوڅو کې خلک لوټ کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_1.mp3', '', 1761754199, 1761754199),
(50900, 'Hosea 7:2', 'Hosea', 7, 2, 'هغوی په دې نه پوهیږي چې د هغوی ټول بد عملونه ماته په یاد دي، خو هغوی په خپلو ګناهونو کې راګېر شوي دي او زه هغه ټول په خپلو سترګو وینم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_2.mp3', '', 1761754199, 1761754199),
(50901, 'Hosea 7:3', 'Hosea', 7, 3, 'څښتن وایي: «خلک په خپلو بدو کارونو باندې پاچا خوشحالوي او په خپلو بدو دسیسو باندې مامورین غولوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_3.mp3', '', 1761754199, 1761754199),
(50902, 'Hosea 7:4', 'Hosea', 7, 4, 'هغوی ټول خاینان او بې‌وفا دي. د هغوی د شهوت لمبې د تنور د هغه اور په شان دي چې نانوای بل ساتلی دی، تر هغې چې خمیره د پخولو دپاره تیاره شوې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_4.mp3', '', 1761754199, 1761754199),
(50903, 'Hosea 7:5', 'Hosea', 7, 5, 'په کومه ورځ چې پاچا جشن جوړوي، نو هغوی پاچا او د هغه مامورین نشه کوي، په داسې حال کې چې پاچا د هغو خلکو سره یوځای کیږي چې په هغه باندې ملنډې وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_5.mp3', '', 1761754199, 1761754199),
(50904, 'Hosea 7:6', 'Hosea', 7, 6, 'د هغوی زړونه لکه د تنور په شان د خپلو دسیسو له امله سوځیږي. هغوی ټوله شپه په خپل قهر کې بې‌ لمبو سوځي او په سهار کې لکه د اور په شان لمبې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_6.mp3', '', 1761754199, 1761754199),
(50905, 'Hosea 7:7', 'Hosea', 7, 7, 'هغوی ټول لکه د سوځوونکي تنور په شان دي، هغوی خپل مشران وژني. د هغوی پاچاهان یو په بل پسې وژل کیږي، خو هېڅوک هم ماته د مرستې دپاره دعا نه کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_7.mp3', '', 1761754199, 1761754199),
(50906, 'Hosea 7:8', 'Hosea', 7, 8, 'څښتن وایي: «د اسراییلو خلک د خپل شاوخوا قومونو سره یوځای شوي دي او د هغې ډوډۍ په شان دي چې یوازې یو مخ یې پوخ وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_8.mp3', '', 1761754199, 1761754199),
(50907, 'Hosea 7:9', 'Hosea', 7, 9, 'او په دې نه پوهیږي چې د پردیو خلکو سره په یوځای کېدلو سره یې خپل قوت له منځه وړی دی. د هغوی ویښتان سپین شوي دي، خو هغوی په دې نه پوهیږي چې دوی زاړه او کمزوري شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_9.mp3', '', 1761754199, 1761754199),
(50908, 'Hosea 7:10', 'Hosea', 7, 10, 'د اسراییلو د خلکو غرور د هغوی په خلاف شاهدي ورکوي، خو بیاهم هغوی زما یعنې د خپل څښتن خدای خواته راونه ګرځېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_10.mp3', '', 1761754199, 1761754199),
(50909, 'Hosea 7:11', 'Hosea', 7, 11, 'د اسراییلو خلک د یوې کم‌عقلې او بې‌شعوره کوترې په شان دي. هغوی کله د مصر نه مرسته غواړي او کله د آشور خواته منډې وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_11.mp3', '', 1761754199, 1761754199),
(50910, 'Hosea 7:12', 'Hosea', 7, 12, 'خو زه به یو جال خپور کړم او څنګه چې هغوی ځي او راځي، نو د مرغانو په شان به یې په کې راګېر کړم. لکه څنګه چې مې هغوی ته ویلي وو، هغوی ته به د هغوی د بدو کارونو په سبب سزا ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea7_verse_12.mp3', '', 1761754199, 1761754199);